public sealed class GetPaymentQueryHandler(IHotelPaymentRepository r, IFrontOfficeExecutionContextAccessor cx, IAuthorizationService a) : IQueryHandler<GetPaymentQuery, HotelPaymentDto> { public async Task<Result<HotelPaymentDto>> HandleAsync(GetPaymentQuery q, CancellationToken ct) => !P.CanView(cx, a, out var p, out var e) ? Result<HotelPaymentDto>.Failure(e!) : await r.GetDtoAsync(p, q.HotelPaymentId, ct) is { } d ? Result<HotelPaymentDto>.Success(d) : Result<HotelPaymentDto>.Failure(Error.Business("PAYMENT_NOT_FOUND", "")); }
