file static class P
{
    public static bool CanView(IFrontOfficeExecutionContextAccessor cx, IAuthorizationService a, out Guid pid, out Error? e)
    { pid = Guid.Empty; if (!a.HasPermission("FrontOffice.Payment.View")) { e = Error.Authorization("PAYMENT_PERMISSION_DENIED", ""); return false; } if (cx.Current is not { } c) { e = Error.Authorization("PAYMENT_PERMISSION_DENIED", ""); return false; } pid = c.Property.PropertyId.Value; e = null; return true; }
}
